import { useState } from 'react';
import { InputText } from 'primereact/inputtext';
import { Dropdown } from 'primereact/dropdown';
import { Button } from 'primereact/button';
import { Message } from 'primereact/message';

import styles from './TrialForm.module.css';

export default function TrialForm() {
    const [formData, setFormData] = useState({
        fullName: '',
        phone: '',
        email: '',
        program: null
    });

    const [errors, setErrors] = useState({});

    const programs = [
        { label: 'Adults Jiu Jitsu', value: 'adults' },
        { label: 'Kids Jiu Jitsu', value: 'kids' },
        { label: 'Women’s Class', value: 'women' },
        { label: 'Beginner Program', value: 'beginner' }
    ];

    const handleChange = (field, value) => {
        setFormData((prev) => ({
            ...prev,
            [field]: value
        }));

        // clear error once user starts fixing field
        setErrors((prev) => ({
            ...prev,
            [field]: ''
        }));
    };

    const validateForm = () => {
        const newErrors = {};

        if (!formData.fullName.trim()) {
            newErrors.fullName = 'Full name is required';
        }

        if (!formData.phone.trim()) {
            newErrors.phone = 'Phone number is required';
        }

        if (!formData.email.trim()) {
            newErrors.email = 'Email is required';
        } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
            newErrors.email = 'Please enter a valid email';
        }

        if (!formData.program) {
            newErrors.program = 'Please select a program';
        }

        return newErrors;
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        const validationErrors = validateForm();

        if (Object.keys(validationErrors).length > 0) {
            setErrors(validationErrors);
            return;
        }

        console.log('Submitted form:', formData);

        // Reset form after submit if you want
        setFormData({
            fullName: '',
            phone: '',
            email: '',
            program: null
        });

        setErrors({});
    };

    return (
        <section className={styles.trialForm}>
            <div className={styles.trialForm__container}>
                <div className={styles.trialForm__logoWrapper}>
                    <img
                        src="https://satoribjjacademy.com/wp-content/uploads/2026/02/Camada-1.png"
                        alt="Satori Brazilian Jiu Jitsu"
                        className={styles.trialForm__logo}
                    />
                </div>

                <h2 className={styles.trialForm__title}>
                    Fill in your details and{' '}
                    <span className={styles.trialForm__titleBold}>
                        schedule your trial class
                    </span>
                </h2>

                <form className={styles.trialForm__form} onSubmit={handleSubmit}>
                    <div className={styles.trialForm__field}>
                        <InputText
                            value={formData.fullName}
                            onChange={(e) => handleChange('fullName', e.target.value)}
                            placeholder="Full Name*"
                            className={`${styles.trialForm__input} ${errors.fullName ? 'p-invalid' : ''}`}
                        />
                        {errors.fullName && (
                            <Message severity="error" text={errors.fullName} className={styles.trialForm__message} />
                        )}
                    </div>

                    <div className={styles.trialForm__field}>
                        <InputText
                            value={formData.phone}
                            onChange={(e) => handleChange('phone', e.target.value)}
                            placeholder="Phone*"
                            className={`${styles.trialForm__input} ${errors.phone ? 'p-invalid' : ''}`}
                        />
                        {errors.phone && (
                            <Message severity="error" text={errors.phone} className={styles.trialForm__message} />
                        )}
                    </div>

                    <div className={styles.trialForm__field}>
                        <InputText
                            value={formData.email}
                            onChange={(e) => handleChange('email', e.target.value)}
                            placeholder="Email*"
                            className={`${styles.trialForm__input} ${errors.email ? 'p-invalid' : ''}`}
                        />
                        {errors.email && (
                            <Message severity="error" text={errors.email} className={styles.trialForm__message} />
                        )}
                    </div>

                    <div className={styles.trialForm__field}>
                        <Dropdown
                            value={formData.program}
                            options={programs}
                            onChange={(e) => handleChange('program', e.value)}
                            placeholder="Select a program*"
                            className={`${styles.trialForm__dropdown} ${errors.program ? 'p-invalid' : ''}`}
                        />
                        {errors.program && (
                            <Message severity="error" text={errors.program} className={styles.trialForm__message} />
                        )}
                    </div>

                    <Button
                        type="submit"
                        label="Schedule a trial class"
                        className={styles.trialForm__button}
                    />
                </form>
            </div>
        </section>
    );
}
